        "dua_hubbaka" to DuaText("מבקש את אהבת אללה", "הו אללה, אני מבקש ממך את אהבתך, את אהבתם של אלה שאוהבים אותך, ומעשים שמביאים אותי לאהבתך. הו אללה, עשה את אהבתך ליקרה לי יותר מאשר לעצמי, ממשפחתי ומהמים הקרים.", "הדואה של דאוד (AS) שסופרה על ידי הנביא ﷺ.", "אהבת אללה היא העושר הגדול ביותר."),
        "dua_filal_khayrat" to DuaText("עושים טוב ועוזבים את הרע", "הו אללה, אני מבקש ממך לאפשר לי לעשות מעשים טובים, לעזוב מעשים רעים ולאהוב את העניים, ותסלח לי ותרחם עליי. וכאשר אתה מתכוון למשפט לעם, קח אותי בלי להישפט. אני מבקש ממך את אהבתך, את אהבתם של אלה שאוהבים אותך, ואת אהבת המעשים המקרבים אותי לאהבתך.", "אללה לימד את הדואה הזו לנביא ﷺ בחלום.", "הנביא ﷺ אמר: זה נכון, אז למד את זה ולמד את זה."),
        "dua_bi_ilmikal_ghayb" to DuaText("תן לי לחיות בזמן שהחיים טובים", "הו אללה, על ידי ידיעתך על הנעלם וכוחך על הבריאה - שמור אותי בחיים כל עוד אתה יודע שהחיים טובים יותר עבורי, וקח אותי כאשר אתה יודע שהמוות טוב לי יותר. הו אללה, אני מבקש ממך פחד ממך בפרטיות ובפומבי, על דבר האמת בשביעות רצון ובכעס, ומתינות בעוני ובעושר.", "דוא התפילה של עמר בן יאסיר (RA) (חלק פתיחה).", "הנביא ﷺ עשה את הדואה הזו בתפילה."),
