        "dua_for_one_i_cursed" to DuaText("למישהו שפגעתי במילים", "הו אללה, כל מאמין שהעלבתי, הפוך זאת לאמצעי להתקרבות אליך עבורו ביום התחייה.", "למישהו שדיברת אליו רע בכעס.", "דואה של הנביא ﷺ."),
        "dua_praising_someone" to DuaText("כשמשבחים מישהו", "אני מחשיב כך וכך, ואללה הוא החשבון שלו, ואני לא ערב לטוהר של איש בפני אללה.", "כשמשבחים מישהו, במקום להגזים.", "הנביא ﷺ לימד נימוס זה של הלל."),
        "dua_being_praised" to DuaText("כשמשבחים אותך", "הו אללה, אל תביא אותי לחשבון על מה שהם אומרים, וסלח לי על מה שהם לא יודעים.", "כששמע את עצמו משבחים - תרגול של מלווה (RA).", "דרך להימנע מתנשאות כשמשבחים."),
